package dev.yiconsole.app

// gen/android is generated by `tauri android init` and not checked in; before building, copy this file to
// gen/android/app/src/main/java/dev/yiconsole/app/MainActivity.kt over the generated one (CI does this).

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.View
import android.webkit.JavascriptInterface
import android.webkit.WebView
import androidx.activity.OnBackPressedCallback
import androidx.activity.enableEdgeToEdge
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MainActivity : TauriActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
  }

  // In edge-to-edge mode (enforced from targetSdk 35) the system no longer shrinks the window for the IME,
  // so the input box ends up under the keyboard. Here we pad the bottom of the content by the keyboard height ourselves:
  // only the part of the keyboard taller than the navigation bar; the page already reserves the nav bar via env(safe-area-inset-bottom).
  override fun onWebViewCreate(webView: WebView) {
    val root = findViewById<View>(android.R.id.content)
    ViewCompat.setOnApplyWindowInsetsListener(root) { v, insets ->
      val ime = insets.getInsets(WindowInsetsCompat.Type.ime()).bottom
      val nav = insets.getInsets(WindowInsetsCompat.Type.navigationBars()).bottom
      v.setPadding(0, 0, 0, maxOf(0, ime - nav))
      insets
    }

    // "Open in another browser": show the system app chooser so the user can pick even if a default browser is set (openUrlExternal in PortsView.tsx).
    // Only http / https are accepted; iframes in the page can reach this interface too, so every other scheme is ignored
    webView.addJavascriptInterface(object {
      @JavascriptInterface
      fun openExternal(url: String) {
        val uri = Uri.parse(url)
        if (uri.scheme != "http" && uri.scheme != "https") return
        runOnUiThread {
          val view = Intent(Intent.ACTION_VIEW, uri).addCategory(Intent.CATEGORY_BROWSABLE)
          val chooser = Intent.createChooser(view, "用其他浏览器打开").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
          try { startActivity(chooser) } catch (_: Exception) {}
        }
      }
    }, "YiConsoleAndroid")

    // The back key / back gesture is handed to the page (back.ts): close a dialog or panel, or go back a page;
    // when there's nothing left, the page first shows "press again to exit"; it only exits on a second press within 2 s (or if the page hasn't loaded yet).
    onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
      override fun handleOnBackPressed() {
        webView.evaluateJavascript("(window.__yiConsoleBack ? window.__yiConsoleBack() : false)") { r ->
          if (r != "true") finish()
        }
      }
    })
  }
}
